from qgis.core import QgsProject

project = QgsProject.instance()
layout_manager = project.layoutManager()
layout = layout_manager.layoutByName("红二十五军长征路线图")

if layout:
    items = layout.items()
    result = f"Layout has {len(items)} items:\n"
    for item in items:
        item_type = type(item).__name__
        try:
            item_id = item.id()
        except:
            item_id = 'no_id'
        try:
            pos = item.pos()
            size = item.rect()
            result += f"  {item_type:30s} | id={item_id:50s} | pos=({pos.x():.2f},{pos.y():.2f}) | size=({size.width():.2f}x{size.height():.2f})\n"
        except:
            result += f"  {item_type:30s} | id={item_id:50s}\n"

    print(result)
else:
    print("Layout not found!")

